-- Malaysia school directory import: 10,216 school codes with published contact emails.
-- Historical KPM June 2022 source: MySchoolList v1.2.0 (10,230 records).
-- 18 missing/malformed emails supplemented from published school contact sources.
-- 14 records with no confirmed email omitted; see malaysia_schools_missing_email.csv.
-- This is NOT a complete current 2026 directory; private/international schools and MRSM are not covered comprehensively.
-- Back up database; apply existing suppress_school_email migration; run whole file in one session.
-- No email sending. Existing schools are never updated. New rows are suppressed.
SET NAMES utf8mb4;
DROP TEMPORARY TABLE IF EXISTS `tmp_malaysia_school_import`;
CREATE TEMPORARY TABLE `tmp_malaysia_school_import` (
  `school_code` VARCHAR(30) NOT NULL PRIMARY KEY,
  `school_name` VARCHAR(255) NOT NULL,
  `school_type` VARCHAR(120) NOT NULL,
  `state` VARCHAR(120) NOT NULL,
  `district` VARCHAR(120) NOT NULL,
  `address` TEXT NULL,
  `school_area_type` VARCHAR(12) NOT NULL,
  `contact_email` VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;










































-- Refuse to insert if the staged row count is incomplete.
SELECT COUNT(*), COALESCE(SUM(contact_email <> ''),0) INTO @my_staged_count,@my_email_count FROM `tmp_malaysia_school_import`;
SELECT @my_staged_count AS staged_schools,@my_email_count AS with_email,10216 AS expected;
SELECT state,COUNT(*) AS staged_schools FROM `tmp_malaysia_school_import` GROUP BY state ORDER BY state;
START TRANSACTION;
SELECT x.school_code,x.school_name,x.school_type,x.state,x.district,x.address,x.school_area_type,x.contact_email,
       '', '', '', 0, 0, 1, 1, 0, 0, 0
FROM `tmp_malaysia_school_import` x
WHERE @my_staged_count = 10216 AND @my_email_count = 10216
AND NOT EXISTS (
  SELECT 1 FROM `schools` s
  WHERE CAST(UPPER(TRIM(s.school_code)) AS BINARY) = CAST(x.school_code AS BINARY)
);
SET @my_new_rows := ROW_COUNT();
COMMIT;
SELECT @my_new_rows AS newly_imported,@my_staged_count AS staged_schools;
SELECT state,COUNT(*) AS total_schools,SUM(suppress_school_email=1) AS email_suppressed
FROM schools GROUP BY state ORDER BY state;
DROP TEMPORARY TABLE IF EXISTS `tmp_malaysia_school_import`;
